-- Reviewed "Mejoras" for JPMG: wording checked against the code, six more that were
-- missing, and everything published so the whole office sees it.

UPDATE `Improvement` SET `afterText` = 'Cada mejora dice qué pasaba antes, qué pasa ahora y, cuando sirve, un ejemplo de conversación. Las que todavía no viste aparecen marcadas como nuevas y el menú muestra cuántas hay. Y en la pestaña Propuestas pueden sugerirnos mejoras: todos ven las propuestas, su estado y nuestra respuesta.', `updatedAt` = CURRENT_TIMESTAMP(3) WHERE `title` = 'Nueva sección Mejoras' AND `producerId` = (SELECT `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL) AND `deletedAt` IS NULL;
UPDATE `Improvement` SET `summary` = 'Cuando alguien de la oficina responde un chat, desde el celular o desde la Bandeja, el bot se corre y no vuelve mientras el cliente siga hablando.', `beforeText` = 'A los 30 minutos de la última respuesta de la oficina el chat volvía solo al bot, aunque el cliente siguiera conversando, y el bot podía saludar con el menú ante un simple "gracias".', `afterText` = 'En horario de atención, el chat sigue con la oficina hasta que pasan 2 horas sin mensajes de nadie, o 4 horas sin que la oficina responda. Fuera de horario vuelve al bot a los 30 minutos sin respuesta. Siempre se puede devolver antes con "Devolver al bot". Y si el cliente cierra con "gracias" o "dale" una charla que tuvo con una persona, el bot no contesta.', `updatedAt` = CURRENT_TIMESTAMP(3) WHERE `title` = 'El bot no interrumpe cuando alguien de la oficina está atendiendo' AND `producerId` = (SELECT `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL) AND `deletedAt` IS NULL;
UPDATE `Improvement` SET `title` = 'Identifica al cliente aunque mande el DNI como le salga', `summary` = 'El bot reconoce el DNI o la patente aunque vengan junto al nombre, con espacios, o dichos en un audio.', `beforeText` = NULL, `afterText` = NULL, `example` = 'Cliente: 24492194 sosa marcelo
NICO: ✅ ¡Listo, te identifiqué! Contame, ¿en qué te doy una mano hoy?', `updatedAt` = CURRENT_TIMESTAMP(3) WHERE `title` = 'Reconoce el DNI o la patente aunque vengan dentro de una frase' AND `producerId` = (SELECT `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL) AND `deletedAt` IS NULL;
UPDATE `Improvement` SET `title` = 'Atención humana global', `summary` = 'Desde Configuración › Asistente se pasan todos los chats a atención humana con un botón: el bot deja de responder y los mensajes siguen entrando a la Bandeja. Los chats que ya tenía tomados una persona quedan como estaban.', `updatedAt` = CURRENT_TIMESTAMP(3) WHERE `title` = 'Modo atención humana' AND `producerId` = (SELECT `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL) AND `deletedAt` IS NULL;
UPDATE `Improvement` SET `summary` = 'En Configuración › Coberturas se elige qué cobertura aparece como "La más elegida" y para qué años de vehículo se recomienda, y se edita qué incluye y qué no incluye cada una. El bot y la web usan esos textos.', `updatedAt` = CURRENT_TIMESTAMP(3) WHERE `title` = 'Configurar las coberturas desde el panel' AND `producerId` = (SELECT `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL) AND `deletedAt` IS NULL;

INSERT INTO `Improvement` (`title`, `summary`, `beforeText`, `afterText`, `example`, `area`, `releasedOn`, `publishedAt`, `createdAt`, `updatedAt`, `producerId`)
SELECT 'Si la póliza tiene deuda, la denuncia pasa a la oficina', 'Si la póliza tiene cuotas vencidas o un pago rechazado, el bot no toma la denuncia solo: le explica al cliente por qué y avisa a un asesor para que revise el caso.', 'El bot podía registrar la denuncia de una póliza con deuda, y la oficina se enteraba después.', NULL, 'NICO: ⚠️ La póliza 2198988 registra cuotas vencidas sin pagar, así que no puedo tomar la denuncia automáticamente: la cobertura puede estar suspendida hasta regularizarlas. Ya le avisé a un asesor para que revise tu caso y te contacte a la brevedad.', 'BOT', '2026-10-05', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL
UNION ALL
SELECT 'La Bandeja muestra quién escribe', 'Si un familiar escribe con el DNI del titular, el chat aparece con el nombre de quien escribe y una nota "Consultó por …" con el titular.', 'El chat figuraba con el nombre del titular aunque escribiera otra persona.', NULL, NULL, 'BANDEJA', '2026-10-05', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL
UNION ALL
SELECT 'Al reactivar el bot ya no se despide de todos', 'Cuando se vuelve a prender el bot después de apagarlo, ya no manda "damos por finalizada esta conversación" a todos los chats que se juntaron mientras estuvo apagado.', 'Al reactivarlo, el mensaje de despedida les llegaba de golpe a todos esos chats, incluso a los de varios días atrás y a los que estaba atendiendo una persona.', 'La despedida por inactividad solo la recibe un chat que el bot estaba atendiendo y que quedó esperando respuesta del cliente.', NULL, 'BOT', '2026-10-05', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL
UNION ALL
SELECT 'Las fotos sueltas ya no se suman a denuncias viejas', 'Una foto que llega sin contexto solo se agrega a una denuncia de las últimas 48 horas. Si no hay ninguna, el bot pregunta para qué es.', 'Se pegaba a la última denuncia del cliente aunque fuera de semanas atrás.', NULL, NULL, 'BOT', '2026-10-09', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL
UNION ALL
SELECT 'De Asuntos pendientes directo al chat', 'Al abrir un aviso de "pidió un asesor" desde Asuntos pendientes, se abre ese chat en la Bandeja.', 'Llevaba a la Bandeja sin ningún chat seleccionado.', NULL, NULL, 'PANEL', '2026-09-30', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL
UNION ALL
SELECT 'Vigencia real de las pólizas', 'Las pólizas muestran si están vigentes, todavía no empezaron, vencidas o anuladas, según sus fechas y anulaciones.', 'Se miraba solo la fecha de fin: una póliza anulada podía figurar vigente, y en el portal aparecían códigos de Triunfo como "REFACTURACION".', 'Una renovación muestra desde qué día rige, y los contadores de pólizas vigentes del panel y del portal siguen la misma regla.', NULL, 'PANEL', '2026-09-30', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL;

UPDATE `Improvement` SET `publishedAt` = CURRENT_TIMESTAMP(3), `releasedOn` = COALESCE(`releasedOn`, CURRENT_DATE()), `updatedAt` = CURRENT_TIMESTAMP(3) WHERE `producerId` = (SELECT `id` FROM `Producer` WHERE `slug` = 'john' AND `deletedAt` IS NULL) AND `publishedAt` IS NULL AND `deletedAt` IS NULL;
